  PRIMARY KEY (`id`),
  KEY `academic_automation_rules_school_id_foreign` (`school_id`),
  CONSTRAINT `academic_automation_rules_school_id_foreign` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE CASCADE
