me',1,1,0,'[{\"id\":\"blk_6a8de3e452ebd\",\"type\":\"hero\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"hero-editorial\",\"title\":\"A Legacy of Learning, Since 1962\",\"description\":\"For more than six decades, <strong>St. Aldric College<\\/strong> has shaped young minds through scholarship, character and service. We invite you to become part of a story still being written.\",\"cta_text\":\"Discover Our Heritage\",\"cta_url\":\"\\/about\",\"secondary_cta_text\":\"Book a Visit\",\"secondary_cta_url\":\"\\/contact\",\"image_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/campus-exterior.svg\",\"layout\":\"image-right\"},{\"id\":\"blk_6a8de3e452ec2\",\"type\":\"marquee_ticker\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"single-row\",\"items\":[{\"label\":\"Founded 1962\"},{\"label\":\"Cambridge & ZIMSEC Accredited\"},{\"label\":\"A Culture of Excellence\"},{\"label\":\"Boarding & Day Scholar\"},{\"label\":\"Faith, Integrity, Diligence\"}]},{\"id\":\"blk_6a8de3e452ecf\",\"type\":\"about_section\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"Our Founding Principles\",\"description\":\"Founded on the conviction that true education tempers the mind with virtue, St. Aldric College remains faithful to three enduring ideals.\",\"mission\":\"To nurture principled, high-achieving leaders through transformative, values-led education.\",\"vision\":\"To set the benchmark for modern education and moral formation across the region.\",\"image_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/campus-quad.svg\"},{\"id\":\"blk_6a8de3e452ed1\",\"type\":\"statistics\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"minimal-editorial\",\"title\":\"The College in Figures\",\"subtitle\":\"Numbers gathered from our record books, updated each term.\"},{\"id\":\"blk_6a8de3e452eea\",\"type\":\"features_grid\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"cards\",\"title\":\"Halls of Distinction\",\"subtitle\":\"The houses and faculties that give the College its character.\",\"features\":[{\"title\":\"The School of Letters\",\"desc\":\"Classics, literature and languages taught with rigour and love.\",\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/library.svg\"},{\"title\":\"The School of Science\",\"desc\":\"Six laboratories for physics, chemistry and biology.\",\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/science-lab.svg\"},{\"title\":\"The School of Arts\",\"desc\":\"Music, drama and fine art under one roof.\",\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/arts-studio.svg\"},{\"title\":\"The Athletic Grounds\",\"desc\":\"Forty acres of fields, courts and a covered pavilion.\",\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/sports-field.svg\"}]},{\"id\":\"blk_6a8de3e452ef1\",\"type\":\"principal_welcome\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"A Word from the Headmaster\",\"principal_name\":\"Dr. Edward Mhlanga\",\"principal_title\":\"Headmaster\",\"description\":\"We ask a great deal of our pupils, because the world asks a great deal of them. In return we offer scholarship that is demanding, character that is formed, and a community that never lets a child walk alone.\",\"image_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/staff-silhouette.svg\"},{\"id\":\"blk_6a8de3e452ef2\",\"type\":\"testimonials\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"large-quote\",\"title\":\"What Families Say\",\"testimonials\":[{\"quote\":\"Three generations of our family have passed through these gates. The standards have never slipped.\",\"name\":\"Mrs. Catherine Ncube\",\"role\":\"Parent, Class of 1988\"},{\"quote\":\"St. Aldric gave my son discipline, curiosity and friends for life. The best decision we ever made.\",\"name\":\"Mr. Tafadzwa Gumbo\",\"role\":\"Parent, Lower Sixth\"},{\"quote\":\"The teachers know each child by name. That is vanishingly rare, and precious.\",\"name\":\"Dr. Amara Okafor\",\"role\":\"Alumna, Class of 2005\"}]},{\"id\":\"blk_6a8de3e452ef9\",\"type\":\"cta_banner\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"Begin Your Association with the College\",\"description\":\"Admissions open for the Michaelmas term. Arrangements to visit may be made through the Registrar\'s office.\",\"cta_text\":\"Apply for Admission\",\"cta_url\":\"\\/apply-online\",\"image_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/assembly-hall.svg\"}]',NULL,NULL,NULL,NULL,'2026-08-25 16:50:12','2026-08-25 16:50:12',NULL,NULL,0,0,NULL,0,0,'heritage-editorial',NULL,'heritage-editorial',NULL,NULL,NULL,NULL,NULL,NULL,0,0,'website','en_US',1,NULL,NULL,NULL,NULL,NULL),(74,5,13,'About Us','about',1,0,0,'[{\"id\":\"blk_6a8de3e452f00\",\"type\":\"hero\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"hero-editorial\",\"title\":\"About the College\",\"description\":\"From our 1962 founding beneath a single fig tree to the present day, St. Aldric College has pursued a single vocation: the formation of the whole person.\",\"cta_text\":\"Meet the Staff\",\"cta_url\":\"#staff\",\"image_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/campus-quad.svg\",\"layout\":\"image-left\"},{\"id\":\"blk_6a8de3e452f07\",\"type\":\"about_section\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"History & Ethos\",\"description\":\"The College was established by the Sisters of St. Aldric with twelve boarders and a library of eighty books. Today we are a co-educational college of more than a thousand pupils, faithful to the same rule of life.\",\"mission\":\"To form leaders of principle through scholarship, service and spiritual grounding.\",\"vision\":\"A College whose graduates are known for competence, integrity and compassion.\",\"image_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/campus-exterior.svg\"},{\"id\":\"blk_6a8de3e452f08\",\"type\":\"team_directory\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"The Faculty\",\"subtitle\":\"Our masters and mistresses are the heart of the College.\"},{\"id\":\"blk_6a8de3e452f1e\",\"type\":\"logo_cloud\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"Affiliations & Accreditations\",\"logos\":[{\"name\":\"Cambridge International\",\"logo_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/logo-placeholder.svg\"},{\"name\":\"ZIMSEC\",\"logo_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/logo-placeholder.svg\"},{\"name\":\"ISA\",\"logo_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/logo-placeholder.svg\"},{\"name\":\"Round Square\",\"logo_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/logo-placeholder.svg\"}]}]',NULL,NULL,NULL,NULL,'2026-08-25 16:50:12','2026-08-25 16:50:12',NULL,NULL,0,0,NULL,0,0,'heritage-editorial',NULL,'heritage-editorial',NULL,NULL,NULL,NULL,NULL,NULL,0,0,'website','en_US',1,NULL,NULL,NULL,NULL,NULL),(75,5,13,'Admissions','apply-online',1,0,0,'[{\"id\":\"blk_6a8de3e452f25\",\"type\":\"hero\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"hero-editorial\",\"title\":\"Admissions\",\"description\":\"Admission is by assessment and interview. Places are limited and are awarded without regard to means.\",\"cta_text\":\"Begin an Application\",\"cta_url\":\"\\/apply-online\",\"image_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/assembly-hall.svg\",\"layout\":\"image-left\"},{\"id\":\"blk_6a8de3e452f26\",\"type\":\"admissions_block\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"The Admission Procedure\",\"subtitle\":\"A simple, transparent process in four stages.\",\"show_form\":true,\"steps\":[{\"title\":\"Submit an Application\",\"description\":\"Complete the online application with the required documents.\"},{\"title\":\"Assessment Day\",\"description\":\"Pupils sit a short assessment in English, mathematics and reasoning.\"},{\"title\":\"Interview & References\",\"description\":\"A conversation with the Headmaster and a reference from the current school.\"},{\"title\":\"Offer & Enrolment\",\"description\":\"Offers are made within three weeks; acceptance completes the enrolment.\"}],\"documents\":[{\"label\":\"Birth certificate\"},{\"label\":\"Latest school report\"},{\"label\":\"Two passport photographs\"},{\"label\":\"Immunisation record\"}],\"fee_note\":\"Scholarships and bursaries are awarded on merit and need. Enquire with the Registrar\'s office for the current schedule of fees.\"},{\"id\":\"blk_6a8de3e452f28\",\"type\":\"faq_accordion\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"Frequently Asked Questions\",\"faqs\":[{\"q\":\"At what ages do you admit pupils?\",\"a\":\"We admit from Year 1 through Lower Sixth. Entry at Year 7 and Year 9 is most common.\"},{\"q\":\"Do you offer boarding?\",\"a\":\"Yes. Three boarding houses \\u2014 two for boys and one for girls \\u2014 accommodate pupils from Year 6 upward.\"},{\"q\":\"Is financial aid available?\",\"a\":\"Yes. A bursary fund, supported by our alumni, assists families of demonstrated need.\"},{\"q\":\"When does the academic year begin?\",\"a\":\"The Michaelmas term begins in early January, with the Lent term in May and the Trinity term in September.\"}]}]',NULL,NULL,NULL,NULL,'2026-08-25 16:50:12','2026-08-25 16:50:12',NULL,NULL,0,0,NULL,0,0,'heritage-editorial',NULL,'heritage-editorial',NULL,NULL,NULL,NULL,NULL,NULL,0,0,'website','en_US',1,NULL,NULL,NULL,NULL,NULL),(76,5,13,'News & Events','news-events',1,0,0,'[{\"id\":\"blk_6a8de3e452f2f\",\"type\":\"hero\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"hero-editorial\",\"title\":\"News & Events\",\"description\":\"The latest dispatches from the College and the dates that shape the school calendar.\",\"cta_text\":\"Subscribe\",\"cta_url\":\"\\/contact\",\"image_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/news-cover.svg\",\"layout\":\"image-left\"},{\"id\":\"blk_6a8de3e452f30\",\"type\":\"dynamic_news\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"From the Headmaster\'s Desk\",\"subtitle\":\"Announcements and letters to families.\"},{\"id\":\"blk_6a8de3e452f31\",\"type\":\"events_calendar\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"The College Calendar\",\"subtitle\":\"Term dates, fixtures and ceremonial occasions.\"}]',NULL,NULL,NULL,NULL,'2026-08-25 16:50:12','2026-08-25 16:50:12',NULL,NULL,0,0,NULL,0,0,'heritage-editorial',NULL,'heritage-editorial',NULL,NULL,NULL,NULL,NULL,NULL,0,0,'website','en_US',1,NULL,NULL,NULL,NULL,NULL),(77,5,13,'Contact Us','contact',1,0,0,'[{\"id\":\"blk_6a8de3e452f37\",\"type\":\"hero\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"hero-editorial\",\"title\":\"Contact the College\",\"description\":\"The Registrar\'s office is at your service. Write, call, or come and walk the grounds yourself.\",\"cta_text\":\"Send an Enquiry\",\"cta_url\":\"#contact\",\"image_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/campus-exterior.svg\",\"layout\":\"image-left\"},{\"id\":\"blk_6a8de3e452f38\",\"type\":\"contact_map\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"Find Us\",\"description\":\"We are a short drive from the city centre, off the Old Salisbury Road.\",\"address\":\"St. Aldric College, Old Salisbury Road, Harare, Zimbabwe\",\"phone\":\"+263 24 270 1234\",\"email\":\"registrar@staldric.edu.zw\",\"hours\":\"Monday\\u2013Friday 08:00\\u201316:00, Saturday 09:00\\u201312:00\"}]',NULL,NULL,NULL,NULL,'2026-08-25 16:50:12','2026-08-25 16:50:12',NULL,NULL,0,0,NULL,0,0,'heritage-editorial',NULL,'heritage-editorial',NULL,NULL,NULL,NULL,NULL,NULL,0,0,'website','en_US',1,NULL,NULL,NULL,NULL,NULL),(78,5,13,'Student Life','student-life',1,0,0,'[{\"id\":\"blk_6a8de3e452f40\",\"type\":\"hero\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"hero-editorial\",\"title\":\"Life Beyond the Classroom\",\"description\":\"Houses, clubs, music, sport and service \\u2014 the everyday texture of a St. Aldric education.\",\"cta_text\":\"Explore the Galleries\",\"cta_url\":\"#gallery\",\"image_url\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/students-outdoor.svg\",\"layout\":\"image-left\"},{\"id\":\"blk_6a8de3e452f60\",\"type\":\"gallery\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"variant\":\"featured-image\",\"title\":\"Scenes from the College\",\"columns\":3,\"images\":[{\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/students-outdoor.svg\",\"caption\":\"Break on the Great Lawn\"},{\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/library.svg\",\"caption\":\"The Old Library\"},{\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/sports-field.svg\",\"caption\":\"First XV, Autumn Fixture\"},{\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/arts-studio.svg\",\"caption\":\"Studio Practice\"},{\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/cafeteria.svg\",\"caption\":\"Refectory at Noon\"},{\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/assembly-hall.svg\",\"caption\":\"Founders\' Day Assembly\"}]},{\"id\":\"blk_6a8de3e452f61\",\"type\":\"video_embed\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"A Day at St. Aldric\",\"video_url\":\"https:\\/\\/www.youtube.com\\/embed\\/dQw4w9WgXcQ\"},{\"id\":\"blk_6a8de3e452f72\",\"type\":\"features_grid\",\"styles\":{\"padding_top\":\"py-20\",\"padding_bottom\":\"py-20\"},\"title\":\"Houses of the College\",\"subtitle\":\"Every pupil belongs to a house, and every house to a tradition.\",\"features\":[{\"title\":\"Ellis House\",\"desc\":\"The oldest house, known for music and debate.\",\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/assembly-hall.svg\"},{\"title\":\"Nduna House\",\"desc\":\"Home of the cross-country and the cadet corps.\",\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/sports-field.svg\"},{\"title\":\"Okapi House\",\"desc\":\"The arts house, with its own theatre company.\",\"image\":\"https:\\/\\/tinwayacademy.lvh.me\\/images\\/placeholders\\/arts-studio.svg\"}]}]',NULL,NULL,NULL,NULL,'2026-08-25 16:50:12','2026-08-25 16:50:12',NULL,NULL,0,0,NULL,0,0,'heritage-editorial',NULL,'heritage-editorial',NULL,NULL,NULL,NULL,NULL,NULL,0,0,'website','en_US',1,NULL,NULL,NULL,NULL,NULL);
