INSERT INTO `cms_site_templates` VALUES (2,4,'Heritage Editorial','Serif display type, navy/cream/gold palette, symmetric grids, subtle fade-in-on-scroll only.',NULL,3,'2026-08-25 16:06:19','2026-08-25 16:06:19'),(3,4,'Cinematic Immersive','Living aurora canvas hero with kinetic reveal headlines, inverting light/dark sections and continuous motion language.',NULL,4,'2026-08-25 16:06:19','2026-08-25 16:06:19'),(4,4,'Modern Vibrant','Bold color-blocked sections, coverflow student-life showcase, continuous marquee ticker.',NULL,5,'2026-08-25 16:06:19','2026-08-25 16:06:19'),(5,4,'Minimalist Academic','Generous whitespace, single accent color, type-driven micro-motion and progressive text highlight.',NULL,6,'2026-08-25 16:06:19','2026-08-25 16:06:19'),(6,4,'Community Warm','Rounded corners, orbit gallery, optional interactive globe for the global community section.',NULL,7,'2026-08-25 16:06:19','2026-08-25 16:06:19'),(7,4,'Coastal Fresh','Breezy coastal palette with soft sky-to-seafoam gradients, a round photo carousel and rounded friendly cards.',NULL,8,'2026-08-25 16:06:19','2026-08-25 16:06:19'),(8,4,'Playful Garden','Cheerful coral/teal/yellow palette for primary schools, oversized rounded shapes, gradient blobs and photo-led sections.',NULL,9,'2026-08-25 16:06:20','2026-08-25 16:06:20'),(9,4,'Emerald Heritage','Deep forest green and antique gold with elegant serif display type, editorial coverflow and refined card systems.',NULL,10,'2026-08-25 16:06:20','2026-08-25 16:06:20'),(10,4,'Neon Frontier','Dark indigo canvas with electric cyan and lime glows, glassmorphism surfaces, mono labels and a coverflow showcase.',NULL,11,'2026-08-25 16:06:20','2026-08-25 16:06:20'),(11,4,'Sunset International','International-school warmth with terracotta sunsets over deep teal, accreditation logo cloud and a global orbit gallery.',NULL,12,'2026-08-25 16:06:20','2026-08-25 16:06:20');
